public class Main {
    static int removeDuplicates(int[] a) {
        if (a.length == 0) {
            return 0;
        }
        int write = 1;
        for (int read = 1; read < a.length; read++) {
            if (a[read] != a[write - 1]) {
                a[write++] = a[read];
            }
        }
        return write;
    }

    public static void main(String[] args) {
        int[] a = {1, 1, 2, 3, 3, 3, 4};
        int n = removeDuplicates(a);
        System.out.println("Unique count: " + n);
        for (int i = 0; i < n; i++) {
            System.out.print(a[i] + " ");
        }
        System.out.println();
    }
}
